import React from 'react';
import './CursoDetalle.css'; // Estilos específicos
import Inscripcion from './Inscripcion'; // Formulario de inscripción

const CursoDetalle = () => {
  // Información del curso único
  const curso = {
    nombre: 'Automatización de Copytrading con IA',
    descripcion:
      'Hemos desarrollado un bot de trading automatizado con ayuda de <span class="highlight">inteligencia artificial</span>, que se integra con plataformas de copytrading y utiliza estrategias probadas.<br /><br />' +
      '¿Listo para comenzar? Inscribite y recibirás en tu correo todos los datos necesarios: el broker con el que operamos para crear tu propia cuenta, y el enlace directo a nuestra cuenta de copytrading.',
    puntos: [
      'Operaciones automatizadas sin intervención manual',
      'Estrategias basadas en datos reales',
      'Uso de inteligencia artificial en decisiones de entrada/salida',
      'Integración con plataformas de copytrading',
      'Acceso gratuito y sin experiencia previa',
    ],
    imagen: '/trading-icon.png',
  };

  return (
    <div className="curso-container">
      <div className="curso-detalle">
        <h1 className="titulo-curso">
          {curso.nombre}
          <img src={curso.imagen} alt={curso.nombre} className="imagen-curso" />
        </h1>

        <p className="descripcion" dangerouslySetInnerHTML={{ __html: curso.descripcion }}></p>

        <ul>
          {curso.puntos.map((punto, index) => (
            <li key={index} dangerouslySetInnerHTML={{ __html: `✅ ${punto}` }}></li>
          ))}
        </ul>
      </div>

      <Inscripcion />
    </div>
  );
};

export default CursoDetalle;
